using Microsoft.AspNetCore.Mvc; using Exercicio14_SistemaCursos.Models; namespace Exercicio14_SistemaCursos.Controllers; public class CursoController:Controller { static List<Curso>C=new(){new Curso{Id=1,Nome="Desenvolvimento Web",CargaHoraria=120,Modalidade="Presencial",Vagas=10,Valor=1200}, new Curso{Id=2,Nome="C#",CargaHoraria=80,Modalidade="Online",Vagas=0,Valor=800}, new Curso{Id=3,Nome="Banco de Dados",CargaHoraria=60,Modalidade="Presencial",Vagas=8,Valor=700}, new Curso{Id=4,Nome="Python",CargaHoraria=80,Modalidade="Online",Vagas=12,Valor=900}, new Curso{Id=5,Nome="Eletrônica",CargaHoraria=100,Modalidade="Presencial",Vagas=5,Valor=1100}, new Curso{Id=6,Nome="Excel",CargaHoraria=40,Modalidade="Online",Vagas=20,Valor=400}, new Curso{Id=7,Nome="Administração",CargaHoraria=100,Modalidade="Presencial",Vagas=0,Valor=950}, new Curso{Id=8,Nome="UX/UI",CargaHoraria=60,Modalidade="Online",Vagas=15,Valor=850}, new Curso{Id=9,Nome="Redes",CargaHoraria=80,Modalidade="Presencial",Vagas=6,Valor=1000}, new Curso{Id=10,Nome="Power BI",CargaHoraria=50,Modalidade="Online",Vagas=10,Valor=750}}; public IActionResult Index()=>View(C); public IActionResult Disponiveis()=>View("Index",C.Where(x=>x.Vagas>0).ToList()); public IActionResult Online()=>View("Index",C.Where(x=>x.Modalidade=="Online").ToList()); public IActionResult Presenciais()=>View("Index",C.Where(x=>x.Modalidade=="Presencial").ToList()); }